 async linkVideo(actionId:string,file:string,sha256:string,window:number[],quality?:any){const p=this.pair(actionId),s=statSync(file);quality??=await this.execute('inspect_motion_quality',{actionId,sourceRevision:p.revision});p.videoSource={file,sha256,bytes:s.size,modifiedMs:s.mtimeMs,window,revision:p.revision,reviewWindows:(quality.inspectionWindows||[]).map((w:any)=>[w.start,w.end])};this.state.sequence++;this.persist();return {actionId,revision:p.revision,videoSource:p.videoSource};}
