 check(p:any,n:number){if(!Number.isInteger(n)||p.revision!==n)throw Error('Stale revision: read get_action again');}
 commit(a:Action,p?:any,save=true){const old=p&&clone(p);this.state.actions[a.id!]={revision:(p?.revision||0)+1,action:clone(a),reference:p?clone(p.action):clone(a),...(p?.category?{category:p.category,metadata:clone(p.metadata)}:{}),history:p?[...p.history,{revision:old.revision,action:old.action,...(old.motionParameters?{motionParameters:old.motionParameters}:{}),...(old.recipe?{recipe:old.recipe}:{}),...(old.semanticSpec?{semanticSpec:old.semanticSpec,buildReceipt:old.buildReceipt}:{}),...(old.metadata?{metadata:old.metadata}:{})}].slice(-100):[]};this.state.preview.actionId=a.id;this.state.preview.time=0;this.state.preview.playing=false;this.state.sequence++;if(save)this.persist();return clone(this.state.actions[a.id!]);}
 async compose(args:any,artifacts?:any){if(typeof args.actionId!=='string'||args.actionId.startsWith('move-')||!Array.isArray(args.steps))throw Error('Invalid composed action');const p=this.state.actions[args.actionId];if(p){if(p.category==='movement')throw Error('ID belongs to a movement');this.check(p,args.expectedRevision);}else if(args.expectedRevision!==0)throw Error('New action requires revision 0');const warnings:string[]=[],steps=args.steps.map((step:any,index:number)=>{if(Object.keys(step).some(k=>!['movementId','revision','speed','transition','contact','blend','travel'].includes(k)))throw Error('Invalid recipe step');const m=this.pair(step.movementId);if(m.category!=='movement'||m.archived)throw Error('Choose an active library movement');this.check(m,step.revision);if(index){const previous=this.pair(args.steps[index-1].movementId);if(previous.profile?.sourceRevision===previous.revision&&m.profile?.sourceRevision===m.revision){const match=compareEndpoints(previous.profile,m.profile);if(match.fit!=='near')warnings.push(`${m.action.name}: endpoint match needs inspection (${match.poseRmsMeters.toFixed(2)} m pose RMS, ${match.rotationRmsDegrees.toFixed(0)}° rotation RMS)`);if(!match.reviewed)warnings.push(`${m.action.name}: connection endpoints have not both been visually reviewed`);}}if(m.metadata.support==='unknown')warnings.push(`${m.action.name}: support/contact unverified`);if(m.metadata.travel==='source')warnings.push(`${m.action.name}: source travel retained; inspect root continuity`);return {action:clone(m.action),speed:step.speed,transition:step.transition,contact:step.contact,blend:step.blend,travel:step.travel};});if(!this.asset){const b=readFileSync(resolve(this.root,'editor/assets/character.glb'));this.asset=await new GLTFLoader().parseAsync(b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength),'');}const model=cloneRig(this.asset.scene),holder=new THREE.Group();holder.add(model);const scale=1.85/new THREE.Box3().setFromObject(model).getSize(new THREE.Vector3()).y;holder.scale.setScalar(scale);const a=composeMovements(model,this.asset.animations,scale,args.actionId,args.name,steps);this.commit(a,p,false);const pair=this.pair(args.actionId);pair.recipe={steps:clone(args.steps),warnings,compiler:args.steps.some((s:any)=>s.blend==='velocity'||s.travel==='continue')?'pose-blend-v2':'pose-blend-v1'};if(artifacts){pair.semanticSpec=clone(artifacts.spec);pair.buildReceipt=clone(artifacts.receipt);}this.state.preview.idle=false;this.persist();return {actionId:a.id,revision:pair.revision,duration:duration(a),phases:a.phases.map(p=>({id:p.id,name:p.name,duration:p.duration})),recipe:pair.recipe};}
